def _asof(name: str, label: str, ts: str) -> Dataset:
    t = f"TO_DATE('{ts}', 'YYYY-MM-DD HH24:MI:SS')"
    return Dataset(name, "extract", f"Creditor open items RECONSTRUCTED as of {label}: postings created before that moment, minus only the FINTAG adjustments made before it.",
                   sql=("SELECT p.postcode, p.entcode, p.entno, p.entdt, p.enttype, p.glcode, p.slcode, p.damount, p.camount, NVL(a.adj, 0) AS adj_t, p.adjamt AS adjamt_now, p.release_status "
                        "FROM SSRK.FINPOST p LEFT JOIN (SELECT x.postcode AS postcode, sum(x.amount) AS adj FROM "
                        "(SELECT postcode1 AS postcode, amount, time FROM SSRK.FINTAG UNION ALL SELECT postcode2 AS postcode, amount, time FROM SSRK.FINTAG) x "
                        f"WHERE x.time < {t} GROUP BY x.postcode) a ON a.postcode = p.postcode "
                        f"WHERE p.entdt >= DATE '2016-01-01' AND p.time >= DATE '2016-01-01' AND p.time < {t} AND p.glcode IN (1000000026, 1000000024, 1000000092, 1000000025) "
                        "AND ABS(NVL(p.damount, 0) - NVL(p.camount, 0)) <> NVL(a.adj, 0) ORDER BY p.postcode FETCH FIRST 40000 ROWS ONLY"))


SSRK_OTSD_ASOF_01: tuple[Dataset, ...] = (
    _asof("r1_asof_0500", "2026-10-05 00:00", "2026-10-05 00:00:00"),
    _asof("r2_asof_0512", "2026-10-05 12:00", "2026-10-05 12:00:00"),
    _asof("r3_asof_0600", "2026-10-06 00:00", "2026-10-06 00:00:00"),
)
