def _asof2(name: str, label: str, ts: str) -> Dataset:
    t = f"TO_DATE('{ts}', 'YYYY-MM-DD HH24:MI:SS')"
    return Dataset(name, "extract", f"Creditor open items RECONSTRUCTED as of {label} (hybrid): FINPOST.ADJAMT as it is now when the posting was not touched after that moment, else the FINTAG adjustments made before it.",
                   sql=("SELECT p.postcode, p.entcode, p.entno, p.entdt, p.enttype, p.glcode, p.slcode, p.damount, p.camount, "
                        f"CASE WHEN p.last_access_time IS NULL OR p.last_access_time < {t} THEN NVL(p.adjamt, 0) ELSE NVL(a.adj, 0) END AS adj_t, "
                        "p.adjamt AS adjamt_now, p.last_access_time, p.release_status "
                        "FROM SSRK.FINPOST p LEFT JOIN (SELECT x.postcode AS postcode, sum(x.amount) AS adj FROM "
                        "(SELECT postcode1 AS postcode, amount, time FROM SSRK.FINTAG UNION ALL SELECT postcode2 AS postcode, amount, time FROM SSRK.FINTAG) x "
                        f"WHERE x.time < {t} GROUP BY x.postcode) a ON a.postcode = p.postcode "
                        f"WHERE p.entdt >= DATE '2016-01-01' AND p.time >= DATE '2016-01-01' AND p.time < {t} AND p.glcode IN (1000000026, 1000000024, 1000000092, 1000000025) "
                        f"AND ABS(NVL(p.damount, 0) - NVL(p.camount, 0)) <> CASE WHEN p.last_access_time IS NULL OR p.last_access_time < {t} THEN NVL(p.adjamt, 0) ELSE NVL(a.adj, 0) END "
                        "ORDER BY p.postcode FETCH FIRST 40000 ROWS ONLY"))


